# ruff: noqa: E501
from uuid import UUID

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

from newsintel.api.dependencies import AnalystAuth
from newsintel.api.ui import COMMON_JS, render_app_page
from newsintel.domain.access import Permission

router = APIRouter(tags=["article-evolution-dashboard"])


@router.get("/articles/{article_id}/evolution", response_class=HTMLResponse)
async def article_evolution_dashboard(article_id: UUID, auth: AnalystAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "viewer")
    can_verify = Permission.CLAIMS_VERIFY.value in auth.permissions
    body = r"""
<section class="page-head">
  <div>
    <div class="eyebrow">Article evolution</div>
    <h1 id="articleTitle"><span class="skeleton" style="display:block;width:min(800px,82vw);height:46px"></span></h1>
    <div id="articleMeta" class="muted"></div>
  </div>
  <div class="toolbar"><a id="intelligenceLink" class="button secondary">Article intelligence</a><a id="eventLink" class="button ghost">Event dossier</a></div>
</section>
<section id="evolutionAlert" aria-live="polite"></section>
<section class="grid four" style="margin-top:18px">
  <div class="metric"><div class="label">Stored versions</div><div class="value" id="mVersions">—</div><div class="hint">Immutable extraction snapshots</div></div>
  <div class="metric"><div class="label">Material changes</div><div class="value" id="mMaterial">—</div><div class="hint">Across adjacent versions</div></div>
  <div class="metric"><div class="label">Correction candidates</div><div class="value" id="mCandidates">—</div><div class="hint">Detection only; human confirmation required</div></div>
  <div class="metric"><div class="label">Registered corrections</div><div class="value" id="mCorrections">—</div><div class="hint">Auditable correction events</div></div>
</section>
<section class="panel" style="margin-top:18px;padding-bottom:0">
  <div class="tabs" role="tablist" aria-label="Article evolution sections">
    <button class="tab active" data-tab="evolution" type="button" role="tab" aria-selected="true">Version evolution</button>
    <button class="tab" data-tab="corrections" type="button" role="tab" aria-selected="false">Corrections</button>
    <button class="tab" data-tab="claims" type="button" role="tab" aria-selected="false">Claim evolution</button>
    <button class="tab" data-tab="impact" type="button" role="tab" aria-selected="false">Downstream impact</button>
  </div>
  <div id="tab-evolution" class="tab-panel active">
    <div class="section-head"><div><h2>Version timeline</h2><div class="muted small">Shows what changed between stored article snapshots. A material change is not automatically a factual correction.</div></div><select id="versionOrder" style="width:auto"><option value="asc">Oldest first</option><option value="desc">Newest first</option></select></div>
    <div id="versionTimeline" class="stack"><div class="skeleton" style="height:240px"></div></div>
  </div>
  <div id="tab-corrections" class="tab-panel">
    <div class="section-head"><div><h2>Correction review</h2><div class="muted small">Candidates are deterministic review signals. Registration requires a human verifier and never rewrites historical verdicts automatically.</div></div><span id="correctionMethod" class="muted small"></span></div>
    <div id="candidateList" class="stack"><div class="skeleton" style="height:140px"></div></div>
    <div class="section-head" style="margin-top:26px"><div><h2>Registered correction history</h2><div class="muted small">Confirmed correction, clarification, update, or retraction events and their direct review flags.</div></div></div>
    <div id="correctionHistory" class="stack"><div class="skeleton" style="height:180px"></div></div>
  </div>
  <div id="tab-claims" class="tab-panel">
    <div class="section-head"><div><h2>Claim evolution</h2><div class="muted small">Tracks claim families across article versions so revised wording does not disappear into the latest snapshot.</div></div><select id="claimFilter" style="width:auto"><option value="all">All families</option><option value="changed">Changed only</option><option value="retired">Not in latest version</option></select></div>
    <div id="claimEvolution" class="stack"><div class="skeleton" style="height:220px"></div></div>
  </div>
  <div id="tab-impact" class="tab-panel">
    <div class="section-head"><div><h2>Correction dependency impact</h2><div class="muted small">Shows claims whose evidence basis depends directly or indirectly on a registered correction. These are review requirements, not automatic verdict reversals.</div></div></div>
    <div id="impactList" class="stack"><div class="skeleton" style="height:180px"></div></div>
  </div>
</section>
<dialog id="correctionDialog" class="ni-dialog">
  <form id="correctionForm" method="dialog">
    <div class="section-head"><div><div class="eyebrow">Human confirmation</div><h2>Register correction event</h2></div><button id="closeCorrection" class="button ghost" type="button">Close</button></div>
    <div class="notice warn"><b>This is an auditable review action.</b> It creates review flags and may invalidate derived artifacts, but it does not silently change prior verification labels.</div>
    <input id="correctionVersion" type="hidden" />
    <label>Correction kind<select id="correctionKind"><option value="update">Update</option><option value="clarification">Clarification</option><option value="factual_correction">Factual correction</option><option value="retraction">Retraction</option></select></label>
    <label>Correction/source URL <input id="correctionSource" type="url" placeholder="https://publisher.example/article" /></label>
    <label>Analyst note <textarea id="correctionNote" rows="5" placeholder="Why this candidate is being confirmed; cite the visible correction/retraction notice or changed assertion."></textarea></label>
    <fieldset style="border:1px solid var(--line);border-radius:12px;padding:12px"><legend style="padding:0 6px;font-weight:800">Affected claims</legend><div class="muted small" style="margin-bottom:9px">Select only claims whose evidence basis may be affected. To intentionally flag the entire target version, explicitly choose all claims.</div><label class="check-row"><input id="allClaimsInVersion" type="checkbox" /> All claims in the target version</label><div id="affectedClaims" class="stack" style="margin-top:9px"></div></fieldset>
    <label class="check-row"><input id="propagateDependencies" type="checkbox" checked /> Propagate dependency review flags to claims that relied on this article</label>
    <label>Maximum dependency depth<select id="dependencyDepth"><option value="1">1 — direct dependencies only</option><option value="2" selected>2 — direct + one indirect layer</option><option value="3">3</option></select></label>
    <div class="toolbar"><button type="submit">Register correction event</button><span id="correctionCandidateContext" class="muted small"></span></div>
  </form>
</dialog>
<dialog id="reviewDialog" class="ni-dialog">
  <form id="reviewForm" method="dialog">
    <div class="section-head"><div><div class="eyebrow">Review flag</div><h2>Mark claim review complete</h2></div><button id="closeReview" class="button ghost" type="button">Close</button></div>
    <input id="reviewFlagId" type="hidden" />
    <div id="reviewFlagContext" class="notice"></div>
    <label>Resolution note <textarea id="reviewNote" rows="5" placeholder="Record what was checked and why the flag can be closed."></textarea></label>
    <div class="toolbar"><button type="submit">Mark reviewed</button></div>
  </form>
</dialog>
"""
    article_id_text = str(article_id)
    can_verify_js = "true" if can_verify else "false"
    extra_css = r"""
.ni-dialog{width:min(720px,calc(100% - 28px));border:1px solid var(--line);border-radius:16px;padding:20px;background:var(--surface);color:var(--text);box-shadow:var(--shadow)}.ni-dialog::backdrop{background:rgba(6,10,20,.56);backdrop-filter:blur(3px)}.ni-dialog form{display:grid;gap:15px}.ni-dialog label{display:grid;gap:7px;font-size:13px;font-weight:700}.ni-dialog textarea{resize:vertical;min-height:110px}.check-row{grid-template-columns:auto 1fr!important;align-items:center!important;font-weight:600!important}.check-row input{width:auto}.version-card{border:1px solid var(--line);border-radius:14px;background:var(--surface-2);overflow:hidden}.version-head{padding:15px;display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.version-body{padding:0 15px 15px}.change-row{border-top:1px solid var(--line);padding:12px 0}.change-texts{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:8px}.change-side{padding:10px;border-radius:10px;background:var(--surface);border:1px solid var(--line);white-space:pre-wrap;line-height:1.55;font-size:13px}.change-side.old{border-left:3px solid var(--bad)}.change-side.new{border-left:3px solid var(--good)}.impact-row{padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--surface-2)}@media(max-width:720px){.change-texts{grid-template-columns:1fr}}
"""
    scripts = f"""<script>{COMMON_JS}
const articleId={article_id_text!r};const canVerify={can_verify_js};let article=null;let versions=null;let detection=null;let corrections=[];let claimHistory=null;let propagation=new Map();
niInitTabs();
function changeKind(kind){{const k=String(kind||'').toLowerCase();if(k.includes('correction')||k.includes('retraction'))return 'bad';if(k.includes('numeric')||k.includes('temporal')||k.includes('replace'))return 'warn';return 'neutral'}}
function severityKind(v){{const x=String(v||'').toLowerCase();if(['critical','high'].includes(x))return 'bad';if(['medium','low'].includes(x))return 'warn';return 'neutral'}}
function verdictKind(v){{const x=String(v||'').toLowerCase();if(x==='supported')return 'good';if(['contradicted','misleading'].includes(x))return 'bad';if(['disputed','unsupported','not_checkable','insufficient_evidence'].includes(x))return 'warn';return 'neutral'}}
function diffTotals(){{return (versions?.entries||[]).reduce((a,e)=>{{const d=e.diff_from_previous;if(!d)return a;a.material+=d.material_change_count||0;a.numeric+=d.numeric_change_count||0;a.temporal+=d.temporal_change_count||0;return a}},{{material:0,numeric:0,temporal:0}})}}
function renderHeader(){{document.getElementById('articleTitle').textContent=article.title;document.title=`Article evolution · ${{article.title}}`;document.getElementById('articleMeta').textContent=`${{article.language||'language unknown'}} · published ${{niDate(article.published_at)}} · observed ${{niDate(article.first_observed_at)}}`;document.getElementById('intelligenceLink').href=`/articles/${{articleId}}/intelligence`;const e=document.getElementById('eventLink');if(article.event_id)e.href=`/events/${{article.event_id}}/intelligence`;else e.hidden=true;const totals=diffTotals();document.getElementById('mVersions').textContent=versions?.version_count||0;document.getElementById('mMaterial').textContent=totals.material;document.getElementById('mCandidates').textContent=detection?.candidates?.length||0;document.getElementById('mCorrections').textContent=corrections.length;if(corrections.some(c=>(c.review_flags||[]).some(f=>f.state==='review_required')))document.getElementById('evolutionAlert').innerHTML='<div class="notice warn"><b>Review required.</b> A registered correction has unresolved claim review flags.</div>';else if((detection?.candidates||[]).length)document.getElementById('evolutionAlert').innerHTML='<div class="notice"><b>Revision candidates detected.</b> These are review signals only; inspect the version diff before registering any correction event.</div>';else document.getElementById('evolutionAlert').innerHTML=''}}
function changeCard(c){{const meta=c.metadata||{{}};return `<div class="change-row"><div class="pill-row">${{niPill(niTitle(c.kind),changeKind(c.kind))}}${{niPill(niTitle(c.significance||'informational'),'neutral')}}${{c.similarity!=null?niPill(`Similarity ${{Math.round(c.similarity*100)}}%`,'neutral'):''}}</div><div class="change-texts">${{c.old_text?`<div class="change-side old"><b>Previous</b><br>${{niEsc(c.old_text)}}</div>`:'<div class="change-side old muted">No previous text</div>'}}${{c.new_text?`<div class="change-side new"><b>New</b><br>${{niEsc(c.new_text)}}</div>`:'<div class="change-side new muted">Text removed</div>'}}</div>${{Object.keys(meta).length?`<div class="muted small" style="margin-top:7px">${{niEsc(Object.entries(meta).map(([k,v])=>`${{niTitle(k)}}: ${{String(v)}}`).join(' · '))}}</div>`:''}}</div>`}}
function renderVersions(){{let rows=[...(versions?.entries||[])];if(document.getElementById('versionOrder').value==='desc')rows.reverse();document.getElementById('versionTimeline').innerHTML=rows.map(v=>{{const d=v.diff_from_previous;const warnings=v.extraction_warnings||[];return `<article class="version-card"><div class="version-head"><div><div class="pill-row">${{niPill(`Version ${{v.version_number}}`,'neutral')}}${{d?.material_change_count?niPill(`${{d.material_change_count}} material`,'warn'):''}}${{d?.numeric_change_count?niPill(`${{d.numeric_change_count}} numeric`,'warn'):''}}${{d?.temporal_change_count?niPill(`${{d.temporal_change_count}} temporal`,'warn'):''}}${{warnings.length?niPill(`${{warnings.length}} extraction warning${{warnings.length===1?'':'s'}}`,'warn'):''}}</div><h3 style="margin:8px 0 3px">${{niEsc(v.title)}}</h3><div class="muted small">Retrieved ${{niDate(v.retrieved_at)}} · ${{niEsc(niTitle(v.extraction_method))}} · hash ${{niEsc(String(v.content_sha256).slice(0,12))}}…</div></div><a class="button ghost" href="${{niEsc(niSafeUrl(v.final_url||v.source_url))}}" target="_blank" rel="noopener noreferrer">Source</a></div><div class="version-body">${{!d?'<div class="notice">First stored version; no previous snapshot exists for comparison.</div>':`<div class="grid four"><div class="metric"><div class="label">Added</div><div class="value">${{d.added_count}}</div></div><div class="metric"><div class="label">Removed</div><div class="value">${{d.removed_count}}</div></div><div class="metric"><div class="label">Replaced</div><div class="value">${{d.replaced_count}}</div></div><div class="metric"><div class="label">Material</div><div class="value">${{d.material_change_count}}</div></div></div>${{(d.changes||[]).length?`<details style="margin-top:12px"><summary><b>Inspect ${{d.changes.length}} detected changes</b></summary><div style="margin-top:6px">${{d.changes.slice(0,30).map(changeCard).join('')}}${{d.changes.length>30?`<div class="muted small">Showing first 30 of ${{d.changes.length}} changes.</div>`:''}}</div></details>`:'<div class="empty" style="margin-top:12px">No structured changes detected.</div>'}}`}}</div></article>`}}).join('')||'<div class="empty">No stored versions are available.</div>'}}
function candidateCard(c){{const already=corrections.find(x=>x.article_version_id===c.to_version_id&&x.correction_kind===c.suggested_kind);return `<div class="evidence-item"><div class="section-head" style="margin:0"><div><div class="pill-row">${{niPill(niTitle(c.suggested_kind),c.suggested_kind==='retraction'?'bad':'warn')}}${{niPill(`Detection confidence ${{Math.round(c.confidence*100)}}%`,'neutral')}}${{c.requires_human_confirmation?niPill('Human confirmation required','warn'):''}}${{already?niPill('Already registered','good'):''}}</div><h3 style="margin:8px 0 4px">Version ${{c.from_version_number}} → ${{c.to_version_number}}</h3><div class="muted small">${{niEsc(c.reason)}}</div></div>${{canVerify&&!already?`<button class="secondary register-correction" type="button" data-kind="${{niEsc(c.suggested_kind)}}" data-version="${{niEsc(c.to_version_id)}}" data-context="Version ${{c.from_version_number}} → ${{c.to_version_number}}">Review & register</button>`:''}}</div><div class="pill-row" style="margin-top:10px">${{niPill(`${{c.material_change_count}} material`,'neutral')}}${{niPill(`${{c.numeric_change_count}} numeric`,'neutral')}}${{niPill(`${{c.temporal_change_count}} temporal`,'neutral')}}</div><div class="muted small" style="margin-top:7px">Detection confidence describes the revision signal, not factual truth.</div></div>`}}
function renderCandidates(){{document.getElementById('correctionMethod').textContent=detection?`${{detection.methodology_version}} · generated ${{niDate(detection.generated_at)}}`:'';const rows=detection?.candidates||[];document.getElementById('candidateList').innerHTML=rows.length?rows.map(candidateCard).join(''):'<div class="empty">No correction/retraction candidates were detected between stored versions.</div>';document.querySelectorAll('.register-correction').forEach(b=>b.addEventListener('click',()=>openCorrection(b.dataset.kind,b.dataset.version,b.dataset.context)))}}
function correctionCard(c){{const flags=c.review_flags||[];const unresolved=flags.filter(f=>f.state==='review_required');const p=propagation.get(c.id);return `<div class="evidence-item"><div class="section-head" style="margin:0"><div><div class="pill-row">${{niPill(niTitle(c.correction_kind),c.correction_kind==='retraction'?'bad':'warn')}}${{unresolved.length?niPill(`${{unresolved.length}} review required`,'warn'):niPill('Review flags clear','good')}}</div><h3 style="margin:8px 0 4px">Registered ${{niDate(c.created_at)}}</h3><div class="muted small">${{niEsc(c.interpretation||'Historical verdicts are preserved while dependent analysis is marked for review.')}}</div></div>${{c.source_url?`<a class="button ghost" href="${{niEsc(niSafeUrl(c.source_url))}}" target="_blank" rel="noopener noreferrer">Correction source</a>`:''}}</div>${{c.note?`<div class="notice" style="margin-top:10px">${{niEsc(c.note)}}</div>`:''}}<div class="grid four" style="margin-top:12px"><div class="metric"><div class="label">Affected claims</div><div class="value">${{(c.affected_claim_ids||[]).length}}</div></div><div class="metric"><div class="label">Review flags</div><div class="value">${{flags.length}}</div></div><div class="metric"><div class="label">Direct dependencies</div><div class="value">${{p?.direct_dependency_count??'—'}}</div></div><div class="metric"><div class="label">Indirect dependencies</div><div class="value">${{p?.indirect_dependency_count??'—'}}</div></div></div>${{flags.length?`<div class="stack" style="margin-top:12px">${{flags.map(flagCard).join('')}}</div>`:''}}</div>`}}
function flagCard(f){{return `<div class="impact-row"><div class="toolbar" style="justify-content:space-between"><div><div class="pill-row">${{niPill(niTitle(f.severity),severityKind(f.severity))}}${{niPill(niTitle(f.state),f.state==='review_required'?'warn':'good')}}</div><div style="margin-top:7px">${{niEsc(f.reason)}}</div><div class="muted small" style="margin-top:5px">${{(f.actions||[]).map(niTitle).join(' · ')}}</div></div><div class="toolbar"><a class="button ghost" href="/claims/${{niEsc(f.claim_id)}}/investigation">Open claim</a>${{canVerify&&f.state==='review_required'?`<button class="secondary review-flag" type="button" data-id="${{niEsc(f.id)}}" data-context="${{niEsc(f.reason)}}">Mark reviewed</button>`:''}}</div></div></div>`}}
function renderCorrections(){{document.getElementById('correctionHistory').innerHTML=corrections.length?corrections.map(correctionCard).join(''):'<div class="empty">No human-confirmed correction events are registered for this article.</div>';document.querySelectorAll('.review-flag').forEach(b=>b.addEventListener('click',()=>openReview(b.dataset.id,b.dataset.context)))}}
function renderClaims(){{const filter=document.getElementById('claimFilter').value;let rows=[...(claimHistory?.families||[])];if(filter==='changed')rows=rows.filter(f=>f.changed_across_versions);if(filter==='retired')rows=rows.filter(f=>!f.active_in_latest_version);document.getElementById('claimEvolution').innerHTML=rows.map(f=>`<details class="claim-card" ${{f.changed_across_versions?'open':''}}><summary><div><div class="pill-row">${{f.changed_across_versions?niPill('Changed across versions','warn'):niPill('Stable wording','neutral')}}${{f.active_in_latest_version?niPill('Active in latest','good'):niPill('Not in latest','warn')}}</div><b style="display:block;margin-top:8px">${{niEsc(f.family_text||f.revisions?.[0]?.claim_text||'Claim family')}}</b><div class="muted small" style="margin-top:5px">Versions ${{f.first_version_number}} → ${{f.last_version_number}}</div></div><span class="muted small">${{(f.revisions||[]).length}} revision${{(f.revisions||[]).length===1?'':'s'}}</span></summary><div class="claim-body"><div class="timeline" style="margin-top:12px">${{(f.revisions||[]).map(r=>`<div class="timeline-item"><div class="pill-row">${{niPill(`v${{r.version_number}}`,'neutral')}}${{r.verification_label?niPill(niTitle(r.verification_label),verdictKind(r.verification_label)):''}}${{r.claim_type?niPill(niTitle(r.claim_type),'neutral'):''}}</div><div style="margin-top:6px"><b>${{niEsc(r.claim_text)}}</b></div><div class="timeline-time">Retrieved ${{niDate(r.retrieved_at)}}${{(r.quantities||[]).length?` · ${{r.quantities.length}} quantified reference${{r.quantities.length===1?'':'s'}}`:''}}${{(r.temporal_references||[]).length?` · ${{r.temporal_references.length}} temporal reference${{r.temporal_references.length===1?'':'s'}}`:''}}</div><div style="margin-top:7px"><a class="button ghost" href="/claims/${{niEsc(r.claim_id)}}/investigation">Investigate this revision</a></div></div>`).join('')}}</div></div></details>`).join('')||'<div class="empty">No claim families match this filter.</div>'}}
function renderImpact(){{const groups=corrections.map(c=>({{correction:c,run:propagation.get(c.id)}})).filter(x=>x.run);document.getElementById('impactList').innerHTML=groups.length?groups.map(({{correction:c,run:p}})=>`<div class="evidence-item"><div class="section-head" style="margin:0"><div><div class="pill-row">${{niPill(niTitle(c.correction_kind),c.correction_kind==='retraction'?'bad':'warn')}}${{p.truncated?niPill('Propagation truncated','warn'):''}}</div><h3 style="margin:8px 0 3px">Correction registered ${{niDate(c.created_at)}}</h3><div class="muted small">Depth ${{p.max_depth}} · ${{p.direct_dependency_count}} direct · ${{p.indirect_dependency_count}} indirect</div></div></div>${{(p.impacts||[]).length?`<div class="stack" style="margin-top:12px">${{p.impacts.map(i=>`<div class="impact-row"><div class="toolbar" style="justify-content:space-between"><div><div class="pill-row">${{niPill(niTitle(i.severity),severityKind(i.severity))}}${{niPill(`Depth ${{i.depth}}`,'neutral')}}</div><div style="margin-top:7px">${{niEsc(i.rationale)}}</div><div class="muted small" style="margin-top:5px">${{(i.actions||[]).map(niTitle).join(' · ')}}</div></div><a class="button ghost" href="/claims/${{niEsc(i.claim_id)}}/investigation">Review claim</a></div></div>`).join('')}}</div>`:'<div class="empty" style="margin-top:12px">No dependent claims were discovered for this correction.</div>'}}</div>`).join(''):'<div class="empty">No correction dependency propagation runs are available yet.</div>'}}
function claimsForVersion(versionId){{const rows=[];for(const family of claimHistory?.families||[])for(const r of family.revisions||[])if(String(r.article_version_id)===String(versionId))rows.push(r);return rows}}
function renderAffectedClaims(versionId){{const rows=claimsForVersion(versionId);document.getElementById('allClaimsInVersion').checked=false;document.getElementById('affectedClaims').innerHTML=rows.length?rows.map(r=>`<label class="check-row impact-row"><input class="affected-claim" type="checkbox" value="${{niEsc(r.claim_id)}}" /><span><b>${{niEsc(r.claim_text)}}</b><span class="muted small" style="display:block">${{r.claim_type?niTitle(r.claim_type):'Claim'}} · version ${{r.version_number}}</span></span></label>`).join(''):'<div class="empty">No extracted claims are attached to this target version. Use “all claims” only if the correction should apply version-wide.</div>'}}
function openCorrection(kind,version,context){{document.getElementById('correctionKind').value=kind||'update';document.getElementById('correctionVersion').value=version||'';document.getElementById('correctionSource').value=article?.canonical_url||'';document.getElementById('correctionNote').value='';document.getElementById('correctionCandidateContext').textContent=context||'';renderAffectedClaims(version);document.getElementById('correctionDialog').showModal()}}
function openReview(id,context){{document.getElementById('reviewFlagId').value=id;document.getElementById('reviewFlagContext').textContent=context||'Review this claim flag before closing it.';document.getElementById('reviewNote').value='';document.getElementById('reviewDialog').showModal()}}
async function registerCorrection(){{const allClaims=document.getElementById('allClaimsInVersion').checked;const selected=[...document.querySelectorAll('.affected-claim:checked')].map(x=>x.value);if(!allClaims&&!selected.length)throw new Error('Select at least one affected claim or explicitly choose all claims in the target version.');const body={{correction_kind:document.getElementById('correctionKind').value,article_version_id:document.getElementById('correctionVersion').value||null,source_url:document.getElementById('correctionSource').value||null,note:document.getElementById('correctionNote').value||null,affected_claim_ids:allClaims?[]:selected,propagate_dependencies:document.getElementById('propagateDependencies').checked,max_dependency_depth:Number(document.getElementById('dependencyDepth').value||2)}};await niApi(`/api/v1/historical/articles/${{articleId}}/corrections`,{{method:'POST',body:JSON.stringify(body)}});niToast('Correction event registered; review flags created where required.','good');document.getElementById('correctionDialog').close();await loadCorrectionData();renderHeader();renderCandidates();renderCorrections();renderImpact()}}
async function resolveReviewFlag(){{const id=document.getElementById('reviewFlagId').value;await niApi(`/api/v1/claim-review-flags/${{id}}/resolve`,{{method:'POST',body:JSON.stringify({{note:document.getElementById('reviewNote').value||null}})}});niToast('Review flag marked reviewed.','good');document.getElementById('reviewDialog').close();await loadCorrectionData();renderHeader();renderCorrections();renderImpact()}}
async function loadCorrectionData(){{[detection,corrections]=await Promise.all([niApi(`/api/v1/historical/articles/${{articleId}}/corrections/detect`),niApi(`/api/v1/historical/articles/${{articleId}}/corrections`)]);propagation=new Map();await Promise.all(corrections.map(async c=>{{const p=await niOptional(`/api/v1/corrections/${{c.id}}/dependency-propagation`);if(p)propagation.set(c.id,p)}}))}}
async function load(){{try{{[article,versions,claimHistory]=await Promise.all([niApi(`/api/v1/articles/${{articleId}}`),niApi(`/api/v1/historical/articles/${{articleId}}/versions`),niApi(`/api/v1/historical/articles/${{articleId}}/claim-history`)]);await loadCorrectionData();renderHeader();renderVersions();renderCandidates();renderCorrections();renderClaims();renderImpact()}}catch(err){{document.getElementById('articleTitle').textContent='Unable to load article evolution';document.getElementById('evolutionAlert').innerHTML=`<div class="error-box">${{niEsc(err.message)}}</div>`}}}}
document.getElementById('allClaimsInVersion').addEventListener('change',e=>document.querySelectorAll('.affected-claim').forEach(x=>{{x.disabled=e.currentTarget.checked;if(e.currentTarget.checked)x.checked=false}}));document.getElementById('versionOrder').addEventListener('change',renderVersions);document.getElementById('claimFilter').addEventListener('change',renderClaims);document.getElementById('closeCorrection').addEventListener('click',()=>document.getElementById('correctionDialog').close());document.getElementById('closeReview').addEventListener('click',()=>document.getElementById('reviewDialog').close());document.getElementById('correctionForm').addEventListener('submit',async e=>{{e.preventDefault();try{{await registerCorrection()}}catch(err){{niToast(err.message,'bad')}}}});document.getElementById('reviewForm').addEventListener('submit',async e=>{{e.preventDefault();try{{await resolveReviewFlag()}}catch(err){{niToast(err.message,'bad')}}}});load();
</script>"""
    return render_app_page(
        title="Article Evolution",
        body=body,
        active="news",
        role=role,
        scripts=scripts,
        extra_css=extra_css,
    )
